body.link:

    // 이거 필요 없을 듯 함.  삭제해야 하나, 아래 HEADER 넘겨주는 부분 참조를 위해 놔 둠 
    <%
    	String ssoToken = request.getParameter("raw_token");
    %>
        <script type="text/javascript" src="<%=CONTEXT_NAME%>/resource/plugin/sepoasoft/login/login.js"></script>
        <script type="text/javascript">

            Sepoa.cache.text.load([{
                url:CONTEXT_NAME+'/resource/ux/admin/langs/'+(Sepoa.request.LANGAUGE || 'KO')+'/POA_BASE.js'
            }]);

            // 삼성 엔지니어링 SSO 시작  , EpTray 와 웹 소켓 통신으로 Json Data 가져옴 

			var Browser = new Object();
			var userAgent = navigator.userAgent.toLowerCase();
			var isIE = userAgent.indexOf('trident');

			// IE 지원 안하면 어떻게 처리해야 하는지 ???
			if(isIE > -1){			
				Alert("IE 는 지원하지 않습니다. Chrome 으로 접속하세요. " ) ;
				return ;
			}

			var websocket = new WebSocket("wss://localhost:29283"); 

			websocket.onopen = function (event) {
				websocket.send('{"rqtype":"getknoxsso","token":"","data":"KCC60TRAY0002"}');			
			}

			//웹소켓 응답 메시지 처리
			websocket.onmessage = function (event) {

				var rpJSON = event.data;  

				var obj = JSON.parse(rpJSON);
				obj = JSON.parse(obj.data);

				if(obj.result == "fail"){
					Alert("Code : " +obj.errorCode  + ":" + obj.errorMsg);
					return;
				}
				websocket.close();
			}
            // 오류 메세지 처리는 어떻게 ?? 
            websocket.onerror = function (event){
				var errmsg = event.data;
			}			

            function SepoaSSO(config)
            {
                sUtils.modules.extend(this, "EventManager");
                sUtils.modules.extend(this, SepoaIndex.prototype.login);
                this.$var = {};
                this.config = $.extend(true, {}, config);

                this.send = function()
                {
                    var config = 
                    {
                        progress:true,
                        nickName:"sepoa.seal.secl.LoginSSO",
                        conType:"CONNECTION",
                        methodName:this.config.service,
                        requestMode:"doServiceAjax",
                        callback:function(so)
                        {
                            var shareObj = {};
                            this.callEvent('onLoginEnd', [so]);
                        }.bind(this)
                    }

                    var data = {};

					// 바로 아래 또는 그 아래 것 중 하나 일 듯. HEADER 라는 것을 어떻게 구분하는지 ??
					// rpJSON 선언 위치..바로 사용 가능 한가 ? ssoToken 은 사용 가능이라서 바로 써 봄...

					data["HEADER"] = {"SSODATA" : rpJSON } ; 

					// data[SSO_DATA] = rpJSON ;

					//data[Sepoa.common.KEY_PARAMS] = sUtils.url.toSepoaParams($.extend(this.config.sendParams||{},{
                    //    SSO_DATA:"<%=rpJSON%>" }),false );

                    //data[Sepoa.common.KEY_PARAMS]= sUtils.url.toSepoaParams($.extend(this.config.sendParams||{},{
                    //    ssoToken:"<%=ssoToken%>" }),false);

                    sUtils.connector.service(config, data);
                }
            }
        </script>

userscript.function:


            var indexObj = $var.module = new SepoaSSO({
                cont:mainFrame,
                mode:Sepoa.request.login || "login",
                service:"forceLogin",
                sendParams:(Sepoa.params)?Sepoa.params.param:null
            });

			// 크롬에서 사용 한다고 하는데 ?? frwk 에서 알아서 변환해주나 ??
            // indexObj.addEventListener("LoginEnd", function(so){

			// ie 에서 사용 한다고 함 . 원 소스가 이걸로 되어 있으니 일단 이것으로 사용함 
            indexObj.attachEvent("onLoginEnd", function(so){
                if(so.status == '1'){
                    location.href = window.CONTEXT_NAME + "/Main.sux";
                } else {
                    location.href = window.CONTEXT_NAME + "/";
                }
            });

            indexObj.send();
